id=$1; out=""; for f in old202 new; do H=$PWD/old202.html; [ $f = new ] && H=/home/user/fitness-app/standalone/index.html; v=$(APPF=$H BN=LeftArm,RightArm,LeftForeArm,RightForeArm,LeftHand,RightHand timeout 250 node bonerotA.js x $id chromeF 120 2>/dev/null | tail -n +2 | awk '{m=0;for(i=2;i<=NF;i++)if($i+0>m)m=$i+0;print m}' | sort -n | tail -1); out="$out ${v:-0}"; done; echo "$id$out"
